cd /dayjs && cat > test/zzprobe.test.js <<'EOF'
import moment from 'moment'
import dayjs from '../src'
import customParseFormat from '../src/plugin/customParseFormat'
import '../src/locale/zh-cn'

dayjs.extend(customParseFormat)

it('probe', () => {
  const cases = [
    ['2018-05-02 上午 01:02:03', 'YYYY-MM-DD A HH:mm:ss', 'zh-cn'],
    ['2018-05-02 下午 01:02:03', 'YYYY-MM-DD A HH:mm:ss', 'zh-cn'],
    ['2018-05-02 01:02:03 上午', 'YYYY-MM-DD hh:mm:ss A', 'zh-cn'],
    ['2018-05-02 01:02:03 下午', 'YYYY-MM-DD hh:mm:ss A', 'zh-cn'],
    ['2018-05-02 01:02:03 AM', 'YYYY-MM-DD hh:mm:ss A', 'en'],
    ['2018-05-02 01:02:03 PM', 'YYYY-MM-DD hh:mm:ss A', 'en'],
  ]
  cases.forEach(([input, format, loc]) => {
    const d = dayjs(input, format, loc)
    const m = moment(input, format, loc)
    console.log(input, '|', format, '| dayjs:', d.format(), d.valueOf(), '| moment:', m.format(), m.valueOf())
  })
})
EOF
